	"version" integer NOT NULL,
	"status" text DEFAULT 'building' NOT NULL,
	"settings" jsonb NOT NULL,
	"content_hash" text,
	"counts" jsonb,
	"redaction_report" jsonb,
	"created_by" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"failed_reason" text,
	CONSTRAINT "fine_tuning_datasets_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON DELETE cascade ON UPDATE no action,
	CONSTRAINT "fine_tuning_datasets_use_case_id_fine_tuning_use_cases_id_fk" FOREIGN KEY ("use_case_id") REFERENCES "public"."fine_tuning_use_cases"("id") ON DELETE cascade ON UPDATE no action,
	CONSTRAINT "fine_tuning_datasets_status_check" CHECK ("fine_tuning_datasets"."status" in ('building', 'ready', 'failed'))
);
